if auth:
    try:
        auth.authenticate_user()
    except Exception:
        pass

SCOPES = [
    "https://www.googleapis.com/auth/spreadsheets",
    "https://www.googleapis.com/auth/drive",
    "https://www.googleapis.com/auth/cloud-platform"
]

import os
sa_path = "Medicaldepartment/client_secret.json"
creds = None

# サービスアカウントまたはADC認証の試行
if os.path.exists(sa_path):
    try:
        # client_secret.jsonがOAuthクライアント認証情報（installed）の場合
        import json
        with open(sa_path) as f:
            data = json.load(f)
        if "service_account" in data or "private_key" in data:
            creds = service_account.Credentials.from_service_account_file(sa_path, scopes=SCOPES)
            print("  → サービスアカウント認証を使用します")
    except Exception:
        pass

if not creds:
    try:
        creds, project = default(scopes=SCOPES)
    except TypeError:
        creds, project = default()
        if hasattr(creds, 'with_scopes'):
            try:
                creds = creds.with_scopes(SCOPES)
            except Exception:
                pass

# トークンのリフレッシュ
if creds and hasattr(creds, 'refresh') and not getattr(creds, 'valid', True):
    try:
        creds.refresh(Request())
    except Exception:
        pass

print("✅ 認証完了")

